-- RUNTIME-TEST SEED (scratch DB only). Mirrors ReferenceSnapshotConsumer when KAFKA_ENABLED=false:
-- replays the latest customer-DB user.snapshot and product-DB product.catalog outbox rows into moneypal_fd reference tables.
SET @OLD_SQL_MODE=@@sql_mode;
-- users
INSERT INTO moneypal_fd.fd_user_ref(fur_user_id,fur_user_uuid,fur_customer_number,fur_full_name,fur_user_status,fur_source_version,fur_synced_at,fur_username,fur_kyc_status,fur_risk_category)
SELECT jt.uid,jt.uuid_,jt.cn,jt.fn,COALESCE(jt.st,'ACTIVE'),e.source_version,UTC_TIMESTAMP(6),jt.un,jt.kyc,jt.risk
FROM moneypal_customer.outbox_event e
JOIN (SELECT event_key,MAX(source_version) mv FROM moneypal_customer.outbox_event WHERE topic='user.snapshot' GROUP BY event_key) m ON m.event_key=e.event_key AND m.mv=e.source_version
JOIN JSON_TABLE(e.payload,'$.user' COLUMNS(uid BIGINT PATH '$.userId',uuid_ VARCHAR(64) PATH '$.userUuid',cn VARCHAR(64) PATH '$.customerNumber',fn VARCHAR(255) PATH '$.fullName',st VARCHAR(32) PATH '$.status',un VARCHAR(255) PATH '$.username',kyc VARCHAR(32) PATH '$.kycStatus' NULL ON EMPTY,risk VARCHAR(32) PATH '$.riskCategory' NULL ON EMPTY)) jt
WHERE e.topic='user.snapshot'
ON DUPLICATE KEY UPDATE fur_user_uuid=IF(VALUES(fur_source_version)>fur_source_version,VALUES(fur_user_uuid),fur_user_uuid),fur_customer_number=IF(VALUES(fur_source_version)>fur_source_version,VALUES(fur_customer_number),fur_customer_number),fur_full_name=IF(VALUES(fur_source_version)>fur_source_version,VALUES(fur_full_name),fur_full_name),fur_user_status=IF(VALUES(fur_source_version)>fur_source_version,VALUES(fur_user_status),fur_user_status),fur_username=IF(VALUES(fur_source_version)>fur_source_version,VALUES(fur_username),fur_username),fur_synced_at=IF(VALUES(fur_source_version)>fur_source_version,UTC_TIMESTAMP(6),fur_synced_at),fur_kyc_status=IF(VALUES(fur_source_version)>fur_source_version,VALUES(fur_kyc_status),fur_kyc_status),fur_risk_category=IF(VALUES(fur_source_version)>fur_source_version,VALUES(fur_risk_category),fur_risk_category),fur_source_version=GREATEST(fur_source_version,VALUES(fur_source_version));
-- latest product events
DROP TEMPORARY TABLE IF EXISTS tmp_pe;
CREATE TEMPORARY TABLE tmp_pe AS SELECT e.* FROM moneypal_product.outbox_event e JOIN (SELECT event_key,MAX(source_version) mv, MAX(id) mid FROM moneypal_product.outbox_event WHERE topic='product.catalog' GROUP BY event_key) m ON m.mid=e.id;
INSERT INTO moneypal_fd.fd_product_ref(fpr_product_id,fpr_product_code,fpr_product_name,fpr_status,fpr_source_version,fpr_synced_at)
SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.aggregateId')) AS UNSIGNED),JSON_UNQUOTE(JSON_EXTRACT(payload,'$.product.pro_product_code')),JSON_UNQUOTE(JSON_EXTRACT(payload,'$.product.pro_product_name')),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.product.pro_status')),'ACTIVE'),source_version,UTC_TIMESTAMP(6) FROM tmp_pe
ON DUPLICATE KEY UPDATE fpr_product_code=VALUES(fpr_product_code),fpr_product_name=VALUES(fpr_product_name),fpr_status=VALUES(fpr_status),fpr_source_version=VALUES(fpr_source_version),fpr_synced_at=UTC_TIMESTAMP(6);
DELETE FROM moneypal_fd.fd_product_currency_ref WHERE product_id IN (SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.aggregateId')) AS UNSIGNED) FROM tmp_pe);
DELETE FROM moneypal_fd.fd_product_rate_ref WHERE product_id IN (SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.aggregateId')) AS UNSIGNED) FROM tmp_pe);
INSERT INTO moneypal_fd.fd_currency_ref(fcr_currency_id,fcr_iso_code,fcr_currency_name,fcr_decimal_places)
SELECT * FROM (SELECT DISTINCT c.cid,c.iso,c.cname,c.dp FROM tmp_pe e JOIN JSON_TABLE(e.payload,'$.currencies[*]' COLUMNS(cid BIGINT PATH '$.cur_currency_id',iso VARCHAR(10) PATH '$.cur_iso_code',cname VARCHAR(100) PATH '$.cur_currency_name' NULL ON EMPTY,dp INT PATH '$.cur_decimal_places')) c) t
ON DUPLICATE KEY UPDATE fcr_iso_code=VALUES(fcr_iso_code),fcr_currency_name=VALUES(fcr_currency_name),fcr_decimal_places=VALUES(fcr_decimal_places);
INSERT INTO moneypal_fd.fd_product_currency_ref(product_id,currency_id,minimum_amount,maximum_amount,is_base_currency,source_version,premature_penalty_points)
SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(e.payload,'$.aggregateId')) AS UNSIGNED),c.cid,c.mn,c.mx,c.base,e.source_version,c.pen FROM tmp_pe e JOIN JSON_TABLE(e.payload,'$.currencies[*]' COLUMNS(cid BIGINT PATH '$.cur_currency_id',mn DECIMAL(20,4) PATH '$.pcc_minimum_amount',mx DECIMAL(20,4) PATH '$.pcc_maximum_amount',base BOOLEAN PATH '$.pcc_is_base_currency',pen DECIMAL(10,4) PATH '$.premature_penalty_points' NULL ON EMPTY)) c;
INSERT INTO moneypal_fd.fd_product_rate_ref(product_id,currency_id,minimum_tenure_months,maximum_tenure_months,annual_rate,compounding_basis,payout_frequency,source_version)
SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(e.payload,'$.aggregateId')) AS UNSIGNED),cr.fcr_currency_id,COALESCE(b.mn1,b.mn2,0),COALESCE(b.mx1,b.mx2,0),b.rate,b.cb,b.pf,e.source_version FROM tmp_pe e JOIN JSON_TABLE(e.payload,'$.rateBands[*]' COLUMNS(iso VARCHAR(10) PATH '$.cur_iso_code',mn1 INT PATH '$.minimumMonth' NULL ON EMPTY,mx1 INT PATH '$.maximumMonth' NULL ON EMPTY,mn2 INT PATH '$.min_month' NULL ON EMPTY,mx2 INT PATH '$.max_month' NULL ON EMPTY,rate DECIMAL(10,6) PATH '$.ro_outcome_value',cb VARCHAR(30) PATH '$.ro_compounding_basis' NULL ON EMPTY,pf VARCHAR(30) PATH '$.ro_payout_frequency' NULL ON EMPTY)) b JOIN moneypal_fd.fd_currency_ref cr ON cr.fcr_iso_code = (b.iso COLLATE utf8mb4_0900_ai_ci);
